// Read-only asset audit: use the production 4bpp/metatile encoder, then decode
// its emitted words. Empty keep-set isolates encoding from a live map's budget.
export function validateNativeTileEncoding(reader,native,cells){const compiler=new MapCompiler(reader,native,{staticArtwork:true,keepMetatiles:new Set()}),rows=[];for(const cell of cells){const p=cell.planes,rule={...cell.rule,renderLayerType:cell.rule?.renderLayerType??cell.rule?.layerType??1,exactArtwork:true,reuseNativeComposite:false},id=compiler.cell(p[0],p.at(-1),-1,rule,{middle:p.length===3?p[1]:null}),decoded=Array.from({length:compiler.layerCount},()=>new Uint8ClampedArray(1024));for(let l=0;l<compiler.layerCount;l++)for(let q=0;q<4;q++){const word=compiler.metatileWord(id,l,q),tile=word&1023,pal=word>>>12;for(let y=0;y<8;y++)for(let x=0;x<8;x++){const sx=word&1024?7-x:x,sy=word&2048?7-y:y,byte=compiler.gfx[tile*32+sy*4+(sx>>>1)],index=sx&1?byte>>>4:byte&15;if(!index)continue;const color=u16(compiler.palettes,pal*32+index*2),j=((Math.floor(q/2)*8+y)*16+q%2*8+x)*4;decoded[l].set([(color&31)*255/31|0,(color>>>5&31)*255/31|0,(color>>>10&31)*255/31|0,255],j);}}const combine=planes=>{const out=new Uint8ClampedArray(1024);for(const plane of planes)for(let j=0;j<1024;j+=4)if(plane[j+3])out.set(plane.subarray(j,j+4),j);return out;};if(!equal(combine(p),combine(decoded)))throw Error('Native encoded background pixels differ from the approved tile.');if(rule.renderLayerType!==1&&p.some((plane,l)=>!equal(plane,decoded[l])))throw Error('Native encoding changed explicit foreground ownership.');rows.push({id,attribute:compiler.attrs[id],rule,decoded});}return{rows,newTiles:compiler.newTiles,newMetatiles:compiler.newMetatiles,graphics:compiler.gfx,metatiles:compiler.meta,attributes:compiler.attrs,palettes:compiler.palettes,stride:compiler.stride};}
